      justify-content: center;
      background: #00d9ff;
      color: #0a0e27;
      padding: 1rem 2.5rem;
      border: none;
      border-radius: 0.5rem;
      font-size: 1.0625rem;
      font-weight: 600;
      letter-spacing: 0.01em;
      cursor: pointer;
      text-decoration: none;
      transition: all 0.2s ease;
      box-shadow: 0 10px 30px rgba(0, 217, 255, 0.2);
      white-space: nowrap;
    }

    .btn-primary:hover {
      background: #00f2ff;
      box-shadow: 0 15px 40px rgba(0, 217, 255, 0.3);
      transform: translateY(-2px);
    }

    .btn-primary:focus {
      outline: 2px solid #00d9ff;
      outline-offset: 2px;
    }

    .btn-secondary {
      background: none;
      color: #00d9ff;
      border: none;
      font-size: 1.0625rem;
      font-weight: 600;
      letter-spacing: 0.01em;
      cursor: pointer;
      text-decoration: none;
      padding: 0.5rem 1.5rem;
      transition: all 0.2s ease;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }

    .btn-secondary:hover {
      color: #00f2ff;
      text-decoration: underline;
    }

    .btn-secondary:focus {
      outline: 2px solid #00d9ff;
      outline-offset: 2px;
      border-radius: 0.25rem;
    }

    .trust-line {
      font-size: 0.9375rem;
      color: #9099b7;
      letter-spacing: 0.01em;
    }

    /* Responsive */
    @media (max-width: 640px) {
      h1 {
        font-size: 2rem;
      }

      .subtext {
        font-size: 1rem;
      }

      .btn-primary {
        font-size: 1rem;
        padding: 0.875rem 2rem;
      }

      .btn-secondary {
        font-size: 1rem;
      }

      .cta-group {
        gap: 0.75rem;
      }
